"use strict";(self.webpackChunkqa_advisor_documentation=self.webpackChunkqa_advisor_documentation||[]).push([[8130],{7735:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"v5-3-0-0","metadata":{"permalink":"/blog/v5-3-0-0","source":"@site/blog/v5-3-0-0.md","title":"v5.3.0.0 \u2014 Reports Are Now Clearer and Easier to Use","description":"This release improves report usability and adds support for collecting Google Search Console data and using a wider range of assistants.","date":"2026-09-09T00:00:00.000Z","tags":[{"inline":true,"label":"release","permalink":"/blog/tags/release"}],"hasTruncateMarker":true,"authors":[],"frontMatter":{"slug":"v5-3-0-0","title":"v5.3.0.0 \u2014 Reports Are Now Clearer and Easier to Use","description":"This release improves report usability and adds support for collecting Google Search Console data and using a wider range of assistants.","tags":["release"],"date":"2026-09-09T00:00:00.000Z"},"unlisted":false,"nextItem":{"title":"Welcome to QA Advisor Documentation","permalink":"/blog/welcome"}},"content":"QA Assistants 5.3.0.0 improves the readability and usability of report screens.\\n\\nThis release also adds support for collecting Google Search Console data and expands the foundation for using a wider range of assistants.\\n\\n\x3c!-- truncate --\x3e\\n\\n## Clearer and Easier-to-Use Reports\\n\\nWe have improved the charts, tables, and date range selection on report screens.\\n\\n* Redesigned charts to make changes in your data easier to understand\\n* Added total rows to report tables\\n* Added controls for choosing which columns to display\\n* Redesigned the date range calendar to make navigating between months and years and selecting a period easier\\n\\n## Support for Collecting Google Search Console Data\\n\\nQA Assistants can now connect to Google Search Console and collect data through its API.\\n\\nAfter you set up the connection and the data has been collected, compatible assistants can use search queries, impressions, clicks, average positions, and other Search Console data.\\n\\nAt this time, QA Assistants does not include a dedicated report screen for viewing Search Console data directly.\\n\\n## Expanded the Foundation for Assistant Features\\n\\nWe have expanded the foundation for assistant features to support a wider range of analysis and information displays in the future.\\n\\nAssistants can now support more capabilities, including date range selection, results displayed with charts and scorecards, and analysis using WordPress post data.\\n\\n\\n## System Requirements\\n\\nStarting with QA Assistants 5.3.0.0, the minimum required PHP version is PHP 7.4.\\n\\nBefore updating, please make sure that your server is running PHP 7.4 or later."},{"id":"welcome","metadata":{"permalink":"/blog/welcome","source":"@site/blog/2025-05-25-welcome.md","title":"Welcome to QA Advisor Documentation","description":"Welcome to the new documentation site for QA Advisor WordPress Analytics!","date":"2025-05-25T00:00:00.000Z","tags":[{"inline":true,"label":"hello","permalink":"/blog/tags/hello"},{"inline":true,"label":"docusaurus","permalink":"/blog/tags/docusaurus"}],"hasTruncateMarker":true,"authors":[],"frontMatter":{"slug":"welcome","title":"Welcome to QA Advisor Documentation","tags":["hello","docusaurus"]},"unlisted":false,"prevItem":{"title":"v5.3.0.0 \u2014 Reports Are Now Clearer and Easier to Use","permalink":"/blog/v5-3-0-0"}},"content":"Welcome to the new documentation site for QA Advisor WordPress Analytics!\\n\\n\x3c!-- truncate --\x3e\\n\\nThis blog will contain updates about new features, tutorials, and best practices for using QA Advisor.\\n\\nStay tuned for more content coming soon."}]}}')}}]);